mapper.sql:
WHERE c.use_yn='Y'
AND (c.cand_no ILIKE '%' || #{q} || '%' OR c.cand_nm ILIKE '%' || #{q} || '%')
AND c.job_cd=#{job}
AND c.grd_cd=#{grade}
AND EXISTS (SELECT 1 FROM hr.cand_skl s WHERE s.cand_id=c.cand_id AND s.skl_cd=#{skill})
AND c.cand_se_cd=#{candType}
AND c.vndr_ptnr_id=#{vendor}
AND c.cntct_stts_cd=#{state}
AND c.asgn_psbl_dt <= #{available}
AND #{today}::date - coalesce(c.last_cntct_dt,c.created_at::date) > 30

mapper.update:
UPDATE hr.cand SET cand_nm=#{input.cand_nm},cand_se_cd=#{input.cand_se_cd},vndr_ptnr_id=#{input.vndr_ptnr_id},job_cd=#{input.job_cd},grd_cd=#{input.grd_cd},hope_untprc_amt=#{input.hope_untprc_amt},asgn_psbl_dt=#{input.avail_dt},
  cntct_stts_cd=CASE WHEN dev_id IS NOT NULL THEN 'SIGNED' WHEN EXISTS(SELECT 1 FROM hr.cand_cntct_hist h WHERE h.cand_id=hr.cand.cand_id) THEN cntct_stts_cd ELSE #{input.cntct_stts_cd} END,
  tel_no=#{input.tel_no},cand_src_cd=#{input.source},memo_desc=#{input.rmrk_desc},updated_by=#{actor}
WHERE cand_id=#{id}
